            | KernelType::MulMvF32F32Reduce
            | KernelType::MulMvF16F32Reduce
            | KernelType::MulMvF32F32_4Reduce
            | KernelType::MulMvF16F32_4Reduce
            | KernelType::MulMvF16F32Pair_4
