            | KernelType::MulMmIdQ2KF32
            | KernelType::MulMmIdQ2KF16
            | KernelType::MulMmIdQ4KF32
            | KernelType::MulMmIdQ4KF16
            | KernelType::MulMmIdIq2XxsF32
            | KernelType::MulMmIdIq2XxsF16
            | KernelType::RmsNormF32_4
