            | KernelType::NegF16
            | KernelType::AbsF16
            | KernelType::StepF16
            | KernelType::ExpF16
            | KernelType::LogF16
            | KernelType::SigmoidF32Scalar
            | KernelType::ReluF32Scalar
            | KernelType::TanhF32Scalar
            | KernelType::GeluF32Scalar
            | KernelType::SiluF32Scalar
