    writeln!(out, "                float4 acc1 = {{0.f, 0.f, 0.f, 0.f}};").unwrap();
    writeln!(out, "                float4 acc2 = {{0.f, 0.f, 0.f, 0.f}};").unwrap();
    writeln!(out, "                for (short i = 0; i < 4; ++i) {{").unwrap();
    writeln!(
        out,
        "                    acc1[0] += yl[2 * i + 0] * (q1[i] & 0x000F);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc1[1] += yl[2 * i + 1] * (q1[i] & 0x0F00);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc1[2] += yl[2 * i + 8] * (q1[i] & 0x00F0);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc1[3] += yl[2 * i + 9] * (q1[i] & 0xF000);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc2[0] += yh[2 * i + 0] * (q2[i] & 0x000F);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc2[1] += yh[2 * i + 1] * (q2[i] & 0x0F00);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc2[2] += yh[2 * i + 8] * (q2[i] & 0x00F0);"
    )
    .unwrap();
    writeln!(
        out,
        "                    acc2[3] += yh[2 * i + 9] * (q2[i] & 0xF000);"
    )
    .unwrap();
    writeln!(out, "                }}").unwrap();
    writeln!(
        out,
        "                sumf[row] += dh[0] * ((acc1[0] + 1.f / 256.f * acc1[1]) * sc8[0] +"
    )
    .unwrap();
    writeln!(out, "                                      (acc1[2] + 1.f / 256.f * acc1[3]) * sc8[1] * 1.f / 16.f +").unwrap();
    writeln!(
        out,
        "                                      (acc2[0] + 1.f / 256.f * acc2[1]) * sc8[4] +"
    )
    .unwrap();
    writeln!(out, "                                      (acc2[2] + 1.f / 256.f * acc2[3]) * sc8[5] * 1.f / 16.f) -").unwrap();
    writeln!(
        out,
        "                             dh[1] * (sumy[0] * sc8[2] + sumy[1] * sc8[3] +"
    )
    .unwrap();
    writeln!(
        out,
        "                                      sumy[2] * sc8[6] + sumy[3] * sc8[7]);"
    )
    .unwrap();
    writeln!(out, "                q1 += args.down_row_bytes / 2;").unwrap();
    writeln!(out, "                sc += args.down_row_bytes / 2;").unwrap();
    writeln!(out, "                dh += args.down_row_bytes / 2;").unwrap();
    writeln!(out, "            }}").unwrap();
    writeln!(out, "            y4 += 4 * QK_K;").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    for (short row = 0; row < nr0 && row0 + (uint)row < args.out_dim; row++) {{"
    )
    .unwrap();
    writeln!(out, "        const float sum_all = simd_sum(sumf[row]);").unwrap();
    writeln!(out, "        if (tiisg == 0u) {{").unwrap();
    writeln!(
        out,
        "            p3[(uint64_t)token * args.out_dim + row0 + (uint)row] = sum_all;"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();

    // This kernel turns a routing id read from p1 into a weight address
    // (`p0 + expert * down_expert_bytes + ...`). The guard emitted above is what
    // stops a bad id becoming a wild pointer -- and it matters that the id is a
    // signed int, because an unchecked negative would wrap under the
    // `(uint64_t)(uint)` cast. Charging the obligation here VERIFIES that guard is
