/// ggml-shell wrapper for q5_K. q5_K extends the q4_K K-quant structure with a 5th
/// bit plane (`qh`): the low nibble comes from `qs` (as in q4_K) and the high bit
/// from `qh`, merged as `q + (h ? 16 : 0)`. This emitter builds the impl through the
/// same structured stages as the q4_K/q8_0 cores (shell prefix, yl/yh block loads,
/// 6-bit scale unpack, dual acc, finalize), specialized for q5_K's qh plane.
/// Reproduces ggml's kernel_mul_mv_q5_K_f32_impl byte-for-byte.
#[allow(dead_code)]
fn emit_mul_mv_q5_K_f32_ggml(out: &mut String) {
    // ---- shell prefix: signature + block/row/GQA setup ----
    writeln!(out, "void kernel_mul_mv_q5_K_f32_impl(").unwrap();
    writeln!(out, "        args_t args,").unwrap();
    writeln!(out, "        device const char * src0,").unwrap();
    writeln!(out, "        device const char * src1,").unwrap();
    writeln!(out, "        device       char * dst,").unwrap();
    writeln!(out, "        threadgroup  char * shmem,").unwrap();
    writeln!(out, "        uint3  tgpig,").unwrap();
    writeln!(out, "        ushort tiisg,").unwrap();
    writeln!(out, "        ushort sgitg) {{").unwrap();
    writeln!(out, "    const short NSG = FC_mul_mv_nsg;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const int nb = args.ne00/QK_K;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const int r0 = tgpig.x;").unwrap();
    writeln!(out, "    const int r1 = tgpig.y;").unwrap();
    writeln!(out, "    const int im = tgpig.z;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const int first_row = (r0 * NSG + sgitg) * nr0;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const uint i12 = im%FC_mul_mv_ne12;").unwrap();
    writeln!(out, "    const uint i13 = im/FC_mul_mv_ne12;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const uint64_t offset0 = first_row*args.nb01 + (i12/FC_mul_mv_r2)*args.nb02 + (i13/FC_mul_mv_r3)*args.nb03;").unwrap();
    writeln!(out, "    const uint64_t offset1 =        r1*args.nb11 + (i12        )*args.nb12 + (i13        )*args.nb13;").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    device const block_q5_K * x = (device const block_q5_K *) (src0 + offset0);"
    )
    .unwrap();
    writeln!(
        out,
        "    device const float     * yy = (device const float      *) (src1 + offset1);"
    )
    .unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    float sumf[nr0]={{0.f}};").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    float yl[16], yh[16];").unwrap();
    writeln!(out).unwrap();
    // ---- 6-bit K-quant scale masks (shared with q4_K) ----
    writeln!(out, "    constexpr uint16_t kmask1 = 0x3f3f;").unwrap();
    writeln!(out, "    constexpr uint16_t kmask2 = 0x0f0f;").unwrap();
    writeln!(out, "    constexpr uint16_t kmask3 = 0xc0c0;").unwrap();
    writeln!(out).unwrap();
    // ---- lane decomposition + q5_K qh masks ----
    writeln!(out, "    const short tid = tiisg/4;").unwrap();
    writeln!(out, "    const short ix  = tiisg%4;").unwrap();
    writeln!(out, "    const short iq  = tid/4;").unwrap();
    writeln!(out, "    const short ir  = tid%4;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const short l0 = 8*ir;").unwrap();
    writeln!(out, "    const short q_offset = 32*iq + l0;").unwrap();
    writeln!(out, "    const short y_offset = 64*iq + l0;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    const uint8_t hm1 = 1u << (2*iq);").unwrap();
    writeln!(out, "    const uint8_t hm2 = hm1 << 1;").unwrap();
    writeln!(out, "    const uint8_t hm3 = hm1 << 4;").unwrap();
    writeln!(out, "    const uint8_t hm4 = hm2 << 4;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    uint16_t sc16[4];").unwrap();
    writeln!(
        out,
        "    thread const uint8_t * sc8 = (thread const uint8_t *)sc16;"
    )
    .unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    device const float * y1 = yy + ix*QK_K + y_offset;"
    )
    .unwrap();
    writeln!(out).unwrap();
    // ---- per-block loop ----
    writeln!(out, "    for (int i = ix; i < nb; i += 4) {{").unwrap();
    writeln!(
        out,
        "        device const uint8_t * q1 = x[i].qs + q_offset;"
    )
    .unwrap();
    writeln!(out, "        device const uint8_t * qh = x[i].qh + l0;").unwrap();
    writeln!(out, "        device const half * dh = &x[i].d;").unwrap();
    writeln!(
        out,
        "        device const uint16_t * a = (device const uint16_t *)x[i].scales + iq;"
    )
    .unwrap();
    writeln!(out).unwrap();
    writeln!(out, "        device const float * y2 = y1 + 128;").unwrap();
    writeln!(out, "        float4 sumy = {{0.f, 0.f, 0.f, 0.f}};").unwrap();
    writeln!(out, "        for (short l = 0; l < 8; ++l) {{").unwrap();
    writeln!(out, "            yl[l+0] = y1[l+ 0]; sumy[0] += yl[l+0];").unwrap();
    writeln!(out, "            yl[l+8] = y1[l+32]; sumy[1] += yl[l+8];").unwrap();
    writeln!(out, "            yh[l+0] = y2[l+ 0]; sumy[2] += yh[l+0];").unwrap();
    writeln!(out, "            yh[l+8] = y2[l+32]; sumy[3] += yh[l+8];").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out).unwrap();
    // ---- per-row: scale unpack + qs/qh merge accumulate + finalize ----
    writeln!(out, "        for (short row = 0; row < nr0; ++row) {{").unwrap();
    writeln!(out, "            device const uint8_t * q2 = q1 + 64;").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "            sc16[0] = a[0] & kmask1;").unwrap();
    writeln!(out, "            sc16[1] = a[2] & kmask1;").unwrap();
    writeln!(
        out,
        "            sc16[2] = ((a[4] >> 0) & kmask2) | ((a[0] & kmask3) >> 2);"
    )
    .unwrap();
    writeln!(
        out,
        "            sc16[3] = ((a[4] >> 4) & kmask2) | ((a[2] & kmask3) >> 2);"
    )
    .unwrap();
    writeln!(out).unwrap();
    writeln!(out, "            float4 acc1 = {{0.f}};").unwrap();
    writeln!(out, "            float4 acc2 = {{0.f}};").unwrap();
    writeln!(out, "            FOR_UNROLL (short l = 0; l < 8; ++l) {{").unwrap();
    writeln!(out, "                uint8_t h = qh[l];").unwrap();
    writeln!(out, "                acc1[0] += yl[l+0] * (q1[l] & 0x0F);").unwrap();
    writeln!(out, "                acc1[1] += yl[l+8] * (q1[l] & 0xF0);").unwrap();
    writeln!(out, "                acc1[2] += yh[l+0] * (q2[l] & 0x0F);").unwrap();
    writeln!(out, "                acc1[3] += yh[l+8] * (q2[l] & 0xF0);").unwrap();
    writeln!(out, "                acc2[0] += h & hm1 ? yl[l+0] : 0.f;").unwrap();
    writeln!(out, "                acc2[1] += h & hm2 ? yl[l+8] : 0.f;").unwrap();
    writeln!(out, "                acc2[2] += h & hm3 ? yh[l+0] : 0.f;").unwrap();
    writeln!(out, "                acc2[3] += h & hm4 ? yh[l+8] : 0.f;").unwrap();
    writeln!(out, "            }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "            sumf[row] += dh[0] * (sc8[0] * (acc1[0]      + 16.f*acc2[0]) +"
    )
    .unwrap();
    writeln!(
        out,
        "                                  sc8[1] * (acc1[1]/16.f + 16.f*acc2[1]) +"
    )
    .unwrap();
    writeln!(
        out,
        "                                  sc8[4] * (acc1[2]      + 16.f*acc2[2]) +"
    )
    .unwrap();
    writeln!(
        out,
        "                                  sc8[5] * (acc1[3]/16.f + 16.f*acc2[3])) -"
    )
    .unwrap();
    writeln!(out, "                         dh[1] * (sumy[0] * sc8[2] + sumy[1] * sc8[3] + sumy[2] * sc8[6] + sumy[3] * sc8[7]);").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "            q1 += args.nb01;").unwrap();
    writeln!(out, "            qh += args.nb01;").unwrap();
    writeln!(out, "            dh += args.nb01/2;").unwrap();
    writeln!(out, "            a  += args.nb01/2;").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "        y1 += 4 * QK_K;").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    // ---- reduce + store ----
    writeln!(out, "    device float * dst_f32 = (device float *) dst + (uint64_t)im*args.ne0*args.ne1 + (uint64_t)r1*args.ne0;").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    for (int row = 0; row < nr0 && first_row + row < args.ne0; ++row) {{"
    )
    .unwrap();
    writeln!(out, "        const float tot = simd_sum(sumf[row]);").unwrap();
    writeln!(out, "        if (tiisg == 0) {{").unwrap();
    writeln!(out, "            dst_f32[first_row + row] = tot;").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
}

