    /// The `mma` lowering must accumulate in f32 and bounds-guard every staged
    /// load. Both are regressions this lowering has actually shipped: a
    /// `simdgroup_half8x8` accumulator measured relative error 1.7e-2 against an
    /// f64 host reference at K=512 -- small-K checks passed, so it survived --
    /// and `simdgroup_load` reading p0/p1 directly ran past the end of A and B
    /// whenever K was not a multiple of 8.
    /// The three simdgroup matmul arms share one body, so what distinguishes
    /// them must be exactly the block size and the operand selection. A shape
    /// decision cannot be read off the operands -- M, N and K are runtime
    /// uniforms -- so it lives in the choice of arm, and these pin that.
    /// The f32-output arm exists to stop callers paying for a conversion the
    /// accumulators never needed, and split-K depends on it: half partials give
    /// back exactly the precision the split protects. These pin both, and that
    /// split-K never ships without its fold.
    #[test]
    fn test_msl_f32out_and_splitk_arms() {
        let mut f32o = String::new();
        emit_matmul_f16_simdgroup_f32out_msl(&mut f32o);
        assert!(!f32o.contains("(half)Cs["), "f32 result must not round through half:\n{f32o}");
        assert!(f32o.contains("simdgroup_store(acc[i][j], p2 +"),
                "an interior block should store straight to the result:\n{f32o}");

        let mut sk = String::new();
        emit_matmul_f16_splitk_msl(&mut sk);
        assert!(sk.contains("const uint sp = tgpig.z;"),
                "split-K takes its K range from the grid's third axis:\n{sk}");
        assert!(sk.contains("& ~7u"), "split-K chunks must stay 8-aligned:\n{sk}");
        assert!(sk.contains("(size_t)sp * M *"), "each split needs its own partial:\n{sk}");
        assert!(!sk.contains("(half)Cs["), "partials must not round through half:\n{sk}");

        let mut red = String::new();
        emit_splitk_reduce_msl(&mut red, "k");
        assert!(red.contains("kernel void k_reduce("), "the fold is named after its kernel:\n{red}");
        assert!(red.contains("acc += part[(size_t)s * n + gid]"), "the fold must sum the partials:\n{red}");
    }

    /// The strided arm exists so an engine need not permute Q, K and V into a
    /// [head][token][dim] packing and permute the result back -- four passes
    /// over the activations per layer that compute nothing. It subsumes the
    /// packed arm, which is expressible as q_hs = seq_len*head_dim, q_ts =
    /// head_dim, and verified so on device: with packed strides it reproduces
    /// the packed arm's residuals exactly across seq_len 1..300 and head_dim
    /// 40..320.
    #[test]
    fn test_msl_attn_gqa_strided_addresses_by_stride() {
        let mut o = String::new();
        emit_attention_gqa_strided_msl(&mut o, "float");
        for needle in [
            "p0 + head * q_hs + q_row * q_ts",
            "p1 + kv_head * kv_hs + k * kv_ts",
            "p2 + kv_head * kv_hs + k * kv_ts",
            "p3 + head * o_hs + q_row * o_ts",
        ] {
            assert!(o.contains(needle), "strided arm must address by stride: {needle}\n{o}");
        }
        // the output carries its own pair: a fused QKV block has a token stride
        // of Nq+Nk+Nv while the result goes to a plain [token][head*dim] buffer
        assert!(!o.contains("p3 + head * q_hs"), "output must not reuse Q's strides:\n{o}");
        // and it is still the online-softmax kernel, with no fixed score window
        assert!(o.contains("simd_sum(part)"), "Q.K must reduce across the simdgroup:\n{o}");
        assert!(!o.contains("scores[256]"), "no fixed score window may return:\n{o}");
    }

    #[test]
    fn test_msl_matmul_arms_differ_by_block() {
        let mut wide = String::new();
        emit_matmul_f16_simdgroup_msl(&mut wide);
        let mut deep = String::new();
        emit_matmul_f16_simdgroup_deepk_msl(&mut deep);
        assert!(wide.contains("BM = 64u, BN = 64u"), "wide arm must block 64x64:\n{wide}");
        assert!(deep.contains("BM = 32u, BN = 32u"), "deep-K arm must block 32x32:\n{deep}");
        assert!(wide.contains("acc[4][4]") && deep.contains("acc[2][2]"),
                "accumulator counts must follow the block size");
        // both are the same lowering, so neither may lose the hardware MMA or
        // the f32 accumulator
        for (n, k) in [("wide", &wide), ("deep", &deep)] {
            assert!(k.contains("simdgroup_multiply_accumulate"), "{n} lost the MMA");
            assert!(k.contains("simdgroup_float8x8"), "{n} lost the f32 accumulator");
        }
    }

    /// The fused projection keeps its three weight matrices separate and picks
    /// one per block; concatenating them on the host would duplicate them.
    #[test]
    fn test_msl_qkv_proj_selects_among_three_weights() {
        let mut o = String::new();
        emit_qkv_proj_f16_msl(&mut o);
        assert!(o.contains("Wsel = p1") && o.contains("Wsel = p2") && o.contains("Wsel = p3"),
                "qkv must select among three weight buffers:\n{o}");
        assert!(o.contains("Ntot = Nq + Nk + Nv"), "qkv output width is the concatenation:\n{o}");
        assert!(o.contains("simdgroup_multiply_accumulate"), "qkv must use the hardware MMA:\n{o}");
    }

    #[test]
    fn test_msl_matmul_simdgroup_accumulates_f32_and_guards_loads() {
        let msl = convert_mlir_to_msl(matmul_simdgroup_f16_mlir()).unwrap();
        assert!(
            msl.contains("simdgroup_float8x8 acc"),
            "mma must accumulate in f32"
        );
        assert!(
            !msl.contains("simdgroup_half8x8 acc"),
            "half accumulator regressed into the mma lowering"
        );
        assert!(
            msl.contains("(gr < M && gc < K) ? p0["),
            "the A stage must be bounds-guarded"
        );
        assert!(
            msl.contains("(gr < K && gc < N) ? p1["),
            "the B stage must be bounds-guarded"
        );
        assert!(
            msl.contains("simdgroup_multiply_accumulate"),
            "mma must lower to the hardware intrinsic"
        );
    }

    #[test]
    fn test_msl_matmul_f16() {
        let msl = convert_mlir_to_msl(matmul_f16_mlir()).unwrap();
        assert!(
            msl.contains("kernel void tile_matmul"),
            "missing kernel name"
        );
        assert!(msl.contains("half acc = 0.0h"), "missing half accumulator");
        assert!(
            msl.contains("p0[m * K + kk] * p1[kk * N + n]"),
            "missing matmul inner loop"
        );
        assert!(msl.contains("p2[m * N + n] = acc"), "missing output write");
        assert!(msl.contains("half"), "missing half type for f16 matmul");
    }

