    #[test]
    fn test_msl_matmul_transposed() {
        let mlir = r#"
module {
  llvm.func @matmul_t(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %m = llvm.mlir.constant(4 : i32) : i32
    %n = llvm.mlir.constant(8 : i32) : i32
    %k = llvm.mlir.constant(16 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg0, %m, %k) : (!llvm.ptr<1>, i32, i32) -> i32
    %b = llvm.call @__tile_load_f32(%arg1, %n, %k) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_matmul_transposed_f32(%a, %b, %m, %n, %k) : (i32, i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %res, %m, %n) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        assert!(
            msl.contains("kernel void matmul_t"),
            "missing kernel:\n{}",
            msl
        );
        // Transposed layout: B[n,k] not B[k,n]
        assert!(
            msl.contains("p1[n * K + k]"),
            "transposed matmul must access B[n,k]:\n{}",
            msl
        );
        assert!(
            msl.contains("p0[m * K + k]"),
            "must access A row-major:\n{}",
            msl
        );
        assert!(
            msl.contains("p2[m * N + n]"),
            "must write C row-major:\n{}",
            msl
        );
        // Flat grid dispatch: one thread per output element
        assert!(msl.contains("gid = row * tcount + tid"), "must compute flat gid:\n{}", msl);
        assert!(msl.contains("gid / N"), "must derive row from flat gid:\n{}", msl);
        assert!(msl.contains("gid % N"), "must derive col from flat gid:\n{}", msl);
        // K-loop unrolled by the backend's declared knob, whatever it is set to.
        // Asserting the knob is honoured (rather than a literal factor) keeps
        // this test valid when the factor is retuned for a new target.
        assert!(
            msl.contains(&format!(
                "k + {} < K; k += {}",
                MATMUL_TRANSPOSED_K_UNROLL - 1, MATMUL_TRANSPOSED_K_UNROLL
            )),
            "K-loop must be unrolled by MATMUL_TRANSPOSED_K_UNROLL ({}):\n{}",
            MATMUL_TRANSPOSED_K_UNROLL, msl
        );
        // ...and must still emit the scalar tail for a non-multiple K.
        assert!(msl.contains("for (; k < K; k++) {"), "missing scalar tail:\n{}", msl);
    }

    /// P2 groundwork: a chain this emitter cannot fold must fail loudly.
    /// Before the guard, `matmul` then `silu` emitted only the silu and stored
    /// a value the kernel never computed — a silent miscompile.
    #[test]
    fn test_msl_unfusable_compute_chain_is_rejected() {
        let mlir = r#"
module {
  llvm.func @mm_silu(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %m = llvm.mlir.constant(32 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg0, %m, %m) : (!llvm.ptr<1>, i32, i32) -> i32
    %b = llvm.call @__tile_load_f32(%arg1, %m, %m) : (!llvm.ptr<1>, i32, i32) -> i32
    %c = llvm.call @__tile_matmul_f32(%a, %b, %m, %m, %m) : (i32, i32, i32, i32, i32) -> i32
    %d = llvm.call @__tile_silu_f32(%c, %m, %m) : (i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %d, %m, %m) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let err = convert_mlir_to_msl(mlir).expect_err("unfusable chain must not lower");
        assert!(err.contains("__tile_matmul_f32") && err.contains("__tile_silu_f32"),
            "error must name both ops:\n{}", err);
        assert!(err.contains("silently"), "error must explain the hazard:\n{}", err);
    }

    /// The declared epilogue fusion still lowers: the guard must not regress
    /// recognized pairs. This is the executable definition of "fusable".
    #[test]
    fn test_msl_declared_fusion_pair_still_lowers() {
        assert!(FUSED_COMPUTE_PAIRS.contains(&("__tile_silu_f32", "__tile_mul_f32")),
            "silu+mul must be a declared epilogue fusion");
    }

    #[test]
    fn test_msl_silu_mul_fusion() {
        // SiLU followed by Mul should fuse into a single SiLUMul kernel
        let mlir = r#"
module {
  llvm.func @gated_mlp(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(8960 : i32) : i32
    %gate = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %up = llvm.call @__tile_load_f32(%arg1, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %silu = llvm.call @__tile_silu_f32(%gate, %gate, %r, %c) : (i32, i32, i32, i32) -> i32
    %fused = llvm.call @__tile_mul_f32(%silu, %up, %r, %c) : (i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %fused, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        assert!(
            msl.contains("kernel void gated_mlp"),
            "missing kernel:\n{}",
            msl
        );
        // Must be a fused kernel: silu + mul in one expression
        assert!(
            msl.contains("exp(-v)"),
            "must have silu computation:\n{}",
            msl
        );
        assert!(
            msl.contains("* p1[gid]"),
            "must multiply with second input:\n{}",
            msl
        );
        // Must have 3 buffers (gate, up, output)
        assert!(msl.contains("p0"), "must have p0 (gate input):\n{}", msl);
        assert!(msl.contains("p1"), "must have p1 (up input):\n{}", msl);
        assert!(msl.contains("p2"), "must have p2 (output):\n{}", msl);
    }

    #[test]
    fn test_msl_silu_standalone() {
        // A standalone SiLU (without following Mul) should NOT fuse
        let mlir = r#"
module {
  llvm.func @silu_only(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(256 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_silu_f32(%a, %a, %r, %c) : (i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg1, %res, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        // Standalone SiLU should have 2 buffers (src, dst), not 3
        assert!(msl.contains("p0[gid]"), "must read from p0:\n{}", msl);
        assert!(msl.contains("p1[gid]"), "must write to p1:\n{}", msl);
        assert!(
            !msl.contains("p2"),
            "standalone SiLU should not have p2:\n{}",
            msl
        );
    }

    #[test]
    fn test_msl_attention_gqa() {
        let mlir = r#"
module {
  llvm.func @gqa_test(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>, %arg3: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %nh  = llvm.mlir.constant(12 : i32) : i32
    %nkv = llvm.mlir.constant(2 : i32) : i32
    %seq = llvm.mlir.constant(16 : i32) : i32
    %dim = llvm.mlir.constant(64 : i32) : i32
    %causal = llvm.mlir.constant(1 : i32) : i32
    %q = llvm.call @__tile_load_f32(%arg0, %nh, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %k = llvm.call @__tile_load_f32(%arg1, %nkv, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %v = llvm.call @__tile_load_f32(%arg2, %nkv, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_attention_gqa_f32(%q, %k, %v, %seq, %dim, %nh, %nkv, %causal) : (i32, i32, i32, i32, i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg3, %res, %nh, %dim) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        assert!(
            msl.contains("kernel void gqa_test"),
            "missing kernel:\n{}",
            msl
        );
        // GQA head grouping
        assert!(
            msl.contains("num_heads / num_kv_heads"),
            "GQA must compute group_size:\n{}",
            msl
        );
        assert!(
            msl.contains("head / group_size"),
            "GQA must map Q head to KV head:\n{}",
            msl
        );
        // Scaled attention
        assert!(
            msl.contains("rsqrt"),
            "GQA must scale by rsqrt(head_dim):\n{}",
            msl
        );
        // Causal masking
        assert!(
            msl.contains("causal"),
            "GQA must check causal flag:\n{}",
            msl
        );
        // Softmax
        assert!(
            msl.contains("exp(dot - m_new)"),
            "GQA must apply a max-shifted softmax:\n{}",
            msl
        );
        assert!(
            msl.contains("l = l * alpha + pw;"),
            "GQA must accumulate an online softmax denominator:\n{}",
            msl
        );
        // REGRESSION GUARD. A fixed-size score window silently dropped every key
        // past it: with `scores[256]` and `min(seq_len, 256u)`, seq_len 300 and
        // 512 returned relative error 6.5e-03 against an f64 reference, first
        // wrong at q_row 266, while 16/128/256 passed. The decode preset is
        // exactly 256, so nothing in the corpus crossed the line.
        assert!(
            !msl.contains("scores[256]"),
            "GQA must not materialise a fixed-size score window:\n{}",
            msl
        );
        assert!(
            !msl.contains("min(seq_len, 256u)"),
            "GQA must attend to the whole sequence, not a 256-key prefix:\n{}",
            msl
        );
    }

    #[test]
    fn test_msl_attention_gqa_params() {
        let mlir = r#"
module {
  llvm.func @gqa_params(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>, %arg3: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %nh = llvm.mlir.constant(12 : i32) : i32
    %nkv = llvm.mlir.constant(2 : i32) : i32
    %seq = llvm.mlir.constant(16 : i32) : i32
    %dim = llvm.mlir.constant(64 : i32) : i32
    %c = llvm.mlir.constant(1 : i32) : i32
    %q = llvm.call @__tile_load_f32(%arg0, %nh, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %k = llvm.call @__tile_load_f32(%arg1, %nkv, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %v = llvm.call @__tile_load_f32(%arg2, %nkv, %dim) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_attention_gqa_f32(%q, %k, %v, %seq, %dim, %nh, %nkv, %c) : (i32, i32, i32, i32, i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg3, %res, %nh, %dim) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        // All GQA-specific params must be present
        assert!(
            msl.contains("seq_len"),
            "GQA must have seq_len param:\n{}",
            msl
        );
        assert!(
            msl.contains("head_dim"),
            "GQA must have head_dim param:\n{}",
            msl
        );
        assert!(
            msl.contains("num_heads"),
            "GQA must have num_heads param:\n{}",
            msl
        );
        assert!(
            msl.contains("num_kv_heads"),
            "GQA must have num_kv_heads param:\n{}",
            msl
        );
        assert!(
            msl.contains("causal"),
            "GQA must have causal param:\n{}",
            msl
        );
    }

    // ── Inference Metal template validation tests ──────────────────────────
    // These verify the hand-written Metal templates used by deepseek_metal
    // for LLM inference have correct structure (kernel signatures, memory
    // access patterns, numerical algorithms).
    //
    // Uses CARGO_MANIFEST_DIR to locate templates portably — works whether
    // compiled from rustc_codegen_tile or mlir_to_aie_tests.

    /// Locate a golden `.metal` template, or `None` if the `deepseek_metal`
    /// fixture crate is not present in the tree (it lives outside the open
    /// `tile_codegen` workspace). Callers skip the assertion when absent so the
    /// suite stays green whether or not the closed fixtures are checked out.
    fn read_template(name: &str) -> Option<String> {
        let manifest = std::env::var("CARGO_MANIFEST_DIR").unwrap();
        let base = std::path::Path::new(&manifest);
        // Walk up to crates/ then into deepseek_metal/templates/ — the LLM
        // inference MSL templates (inference_kernels.metal, matmul_transposed.metal)
        // live there; tile_metal_py holds a different (batch/vq) template set.
        let templates = base
            .parent()
            .unwrap()
            .join("deepseek_metal")
            .join("templates");
        std::fs::read_to_string(templates.join(name)).map_or_else(
            |e| {
                if e.kind() == std::io::ErrorKind::NotFound {
                    None
                } else {
                    panic!("cannot read {}: {}", name, e)
                }
            },
            Some,
        )
    }

    // -- matmul_transposed.metal --

    #[test]
    fn test_template_matmul_transposed_signature() {
        let Some(src) = read_template("matmul_transposed.metal") else { return };
        assert!(
            src.contains("kernel void matmul_transposed("),
            "missing matmul_transposed kernel"
        );
        assert!(src.contains("device const float* A"), "missing A buffer");
        assert!(src.contains("device const float* B"), "missing B buffer");
        assert!(
            src.contains("device float*       C"),
            "missing C output buffer"
        );
        assert!(src.contains("constant uint&      M"), "missing M dimension");
        assert!(src.contains("constant uint&      K"), "missing K dimension");
        assert!(src.contains("constant uint&      N"), "missing N dimension");
    }

    #[test]
    fn test_template_matmul_transposed_inner_loop() {
        let Some(src) = read_template("matmul_transposed.metal") else { return };
        assert!(
            src.contains("B[col * K + k]"),
            "matmul_transposed must access B in transposed layout"
        );
        assert!(
            src.contains("A[row * K + k]"),
            "matmul_transposed must access A row-major"
        );
        assert!(src.contains("C[row * N + col]"), "must write C row-major");
    }

    #[test]
    fn test_template_matmul_transposed_unroll() {
        let Some(src) = read_template("matmul_transposed.metal") else { return };
        assert!(src.contains("k + 3 < K; k += 4"), "missing 4x loop unroll");
        assert!(
            src.contains("A[row * K + k + 1]"),
            "missing unroll offset +1"
        );
        assert!(
            src.contains("A[row * K + k + 2]"),
            "missing unroll offset +2"
        );
        assert!(
            src.contains("A[row * K + k + 3]"),
            "missing unroll offset +3"
        );
    }

