    // ── Decode-optimized kernel tests ──

    fn mul_mv_id_q6_K_down_f32_mlir() -> &'static str {
        // M134 (moe.metal:2239) glm_q6_K_down_f32 — q6_K down-proj sibling of the
        // sum6 family. 4 bufs (src0s, src1, dst, ids); 8 uniforms. q6_K block =
        // 210 B (d LAST). ne00=256, ne0=16 → nb=1. NB01=210, NB02=16*210=3360,
        // EXPERT_SLOTS=6, TOKENS=2 → NB11=256*4=1024 (per slot), NB12=6*1024=6144
        // (per token), NB1=16*4=64, NBI1=6*4=24.
        r#"
module {
  llvm.func @ds4_kernel_mul_mv_id_q6_K_down_f32(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>, %arg3: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %ne00 = llvm.mlir.constant(256  : i32) : i32
    %ne0  = llvm.mlir.constant(16   : i32) : i32
    %nbi1 = llvm.mlir.constant(24   : i32) : i32
    %nb01 = llvm.mlir.constant(210  : i32) : i32
    %nb02 = llvm.mlir.constant(3360 : i32) : i32
    %nb11 = llvm.mlir.constant(1024 : i32) : i32
    %nb12 = llvm.mlir.constant(6144 : i32) : i32
    %nb1  = llvm.mlir.constant(64   : i32) : i32
    %r = llvm.call @__tile_mul_mv_id_q6_K_down_f32(%arg0, %arg1, %arg2, %arg3, %ne00, %ne0, %nbi1, %nb01, %nb02, %nb11, %nb12, %nb1) : (!llvm.ptr<1>, !llvm.ptr<1>, !llvm.ptr<1>, !llvm.ptr<1>, i32, i32, i32, i32, i32, i32, i32, i32) -> i32
    llvm.return
  }
}
"#
    }

    #[test]
    fn test_msl_mul_mv_id_q6_K_down_f32() {
        let msl = convert_mlir_to_msl(mul_mv_id_q6_K_down_f32_mlir()).unwrap();
        assert!(msl.contains("kernel void ds4_kernel_mul_mv_id_q6_K_down_f32"), "missing kernel name");
        // q6_K block struct with `half d` LAST (unlike q4_K where d/dmin are first).
        assert!(msl.contains("struct block_q6_K"), "missing block_q6_K typedef");
        assert!(msl.contains("char  scales[QK_K/16]"), "missing q6_K scales[16]");
        // Q6_K-specific 6-bit assembly: low nibble | 2-bit-high shifted into bit 4.
        assert!(msl.contains("(h & kmask1) << 4u"), "missing qh 2-bit-high << 4 assembly");
        assert!(msl.contains("kmask1") && msl.contains("kmask4"), "missing kmask1..4");
        assert!(msl.contains("- 32)"), "missing q6_K (q - 32) bias");
        assert!(msl.contains("q_offset_l") && msl.contains("q_offset_h"), "missing q6_K q_offset layout");
        assert!(msl.contains("simd_sum(sumf[row])"), "missing simd_sum finalize");
        // 6-slot expert-combine (down-proj fused slot-accumulate).
        assert!(msl.contains("expert_slot < 6"), "missing 6-slot expert-combine loop");
        // Must NOT carry q4_K-only markers (dmin / kmask 0x3f3f / 1/256 scale).
        assert!(!msl.contains("0x3f3f"), "q4_K KMASK1 leaked into q6_K kernel");
        assert!(!msl.contains("1.0f/256.0f"), "q4_K 1/256 scale leaked into q6_K kernel");
        assert!(!msl.contains("dmin"), "q4_K dmin leaked into q6_K kernel");
    }

    fn matvec_f16_mlir() -> &'static str {
        r#"
module {
  llvm.func @matvec_f16(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(1536 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %b = llvm.call @__tile_load_f32(%arg1, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_matvec_f16(%a, %b, %r, %c) : (i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %res, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#
    }

    #[test]
    fn test_msl_matvec_f16_cooperative_reduction() {
        let msl = convert_mlir_to_msl(matvec_f16_mlir()).unwrap();
        // Must have cooperative thread attributes
        assert!(
            msl.contains("thread_index_in_threadgroup"),
            "missing tid attribute"
        );
        assert!(
            msl.contains("thread_index_in_simdgroup"),
            "missing simd_lane attribute"
        );
        assert!(
            msl.contains("simdgroup_index_in_threadgroup"),
            "missing simd_id attribute"
        );
        // Mixed precision: p1 must be half*, p0/p2 must be float*
        assert!(msl.contains("half* p1"), "p1 (weights) must be half*");
        assert!(msl.contains("float* p0"), "p0 (activation) must be float*");
        assert!(msl.contains("float* p2"), "p2 (output) must be float*");
        // Cooperative reduction pattern
        assert!(msl.contains("simd_sum(sum)"), "missing simd_sum reduction");
        assert!(
            msl.contains("threadgroup float shared"),
            "missing threadgroup shared memory"
        );
        assert!(msl.contains("threadgroup_barrier"), "missing barrier");
        // Must read f16 weight and convert to float
        assert!(
            msl.contains("float(p1["),
            "must convert half to float in MAC"
        );
    }

