    #[test]
    fn test_msl_matvec_i8_v4() {
        let msl = convert_mlir_to_msl(matvec_i8_v4_mlir()).unwrap();
        // Cooperative thread attributes (same reduction shape as matvec_f16).
        assert!(
            msl.contains("thread_index_in_simdgroup"),
            "missing simd_lane attribute"
        );
        assert!(
            msl.contains("simdgroup_index_in_threadgroup"),
            "missing simd_id attribute"
        );
        // Buffer types: p1=int8 weight (char*), p3=per-row scale (half*), p0/p2=float*.
        assert!(
            msl.contains("char* p1"),
            "p1 (weights) must be char* (int8)"
        );
        assert!(msl.contains("half* p3"), "p3 (row scale) must be half*");
        assert!(msl.contains("float* p0"), "p0 (activation) must be float*");
        assert!(msl.contains("float* p2"), "p2 (output) must be float*");
        // p2 must be WRITABLE (not const) and p3 (scale) const.
        assert!(
            !msl.contains("const  float* p2"),
            "p2 (output) must be writable, not const"
        );
        assert!(msl.contains("const  half* p3"), "p3 (scale) must be const");
        // Vectorized loads: float4 activation + char4 weight, dot-accumulated.
        assert!(msl.contains("float4* a4"), "missing float4 activation load");
        assert!(
            msl.contains("char4*  w4") || msl.contains("char4* w4"),
            "missing char4 weight load"
        );
        assert!(
            msl.contains("dot(a4[i], float4(w4[i]))"),
            "missing vectorized dot product"
        );
        // Cooperative reduction + per-row scale on write.
        assert!(msl.contains("simd_sum(sum)"), "missing simd_sum reduction");
        assert!(
            msl.contains("threadgroup float shared"),
            "missing shared memory"
        );
        assert!(
            msl.contains("total * float(p3[row])"),
            "output must apply the per-row f16 scale"
        );
    }

