    #[test]
    fn test_msl_laguna_q4_K_routed_down_pipeline() {
        let mlir = r#"
module {
  llvm.func @laguna_q4_K_routed_down_f32(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>, %arg3: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(256 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg2, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_laguna_q4_K_routed_down_f32(%a, %r, %c) : (i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg3, %res, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let msl = convert_mlir_to_msl(mlir).unwrap();
        assert!(
            msl.contains("struct GlmRoutedMoeArgs {"),
            "missing routed args struct"
        );
        assert!(
            msl.contains("kernel void laguna_q4_K_routed_down_f32"),
            "missing kernel"
        );
        assert!(
            msl.contains("device const  char* p0 [[ buffer(0) ]]"),
            "p0 (down) must be const char"
        );
        assert!(
            msl.contains("device const  int* p1 [[ buffer(1) ]]"),
            "p1 (selected) must be const int"
        );
        assert!(
            msl.contains("device const  float* p2 [[ buffer(2) ]]"),
            "p2 (mid) must be const float"
        );
        assert!(
            msl.contains("device  float* p3 [[ buffer(3) ]]"),
            "p3 (out) must be writable float"
        );
        assert!(
            msl.contains("constant GlmRoutedMoeArgs& args [[ buffer(4) ]]"),
            "missing args uniform"
        );
    }

