    /// Byte-identity gate: the committed runtime artifact
    /// `benchmarks/ds4_msl/emitted/laguna.metal` (baked into the ds4_metal
    /// KERNEL_SOURCES / emitted_lib) MUST equal fresh mlir_to_msl output. This is
    /// the same discipline as the other emitted kernels — the codegen is the source
    /// of truth; regenerate with `cargo run -p mlir_to_msl_tests --bin emit_laguna`.
    #[test]
    fn test_laguna_emitted_metal_byte_identity() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../benchmarks/ds4_msl/emitted/laguna.metal"
        );
        let committed = std::fs::read_to_string(path).unwrap_or_else(|e| {
            panic!("committed {path} missing ({e}); run `cargo run -p mlir_to_msl_tests --bin emit_laguna`")
        });
        let fresh = convert_mlir_to_msl(laguna_runtime_mlir()).unwrap();
        assert_eq!(
            committed, fresh,
            "committed laguna.metal has drifted from mlir_to_msl output; regenerate with `cargo run -p mlir_to_msl_tests --bin emit_laguna`"
        );
    }

    /// Kernel BODIES of one MSL source: the lines strictly inside each
    /// `kernel void … { … }`, signature and braces excluded.
    ///
    /// Body-level, because these emitters write only the body — the signature
    /// and braces are produced by `convert_mlir_to_msl` from the MLIR. Comparing
    /// whole kernels would report drift on every artifact for a reason that has
    /// nothing to do with the emitter.
    fn kernel_bodies(src: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut cur: Option<String> = None;
        let mut depth = 0i32;
        let mut opened = false;
        for line in src.lines() {
            if cur.is_none() && line.trim_start().starts_with("kernel void ") {
                cur = Some(String::new());
                depth = 0;
                opened = false;
            }
            let Some(buf) = cur.as_mut() else { continue };
            let before = depth;
            depth += line.matches('{').count() as i32;
            depth -= line.matches('}').count() as i32;
            if !opened {
                // Skip the signature lines; the body starts after the brace that
                // first takes us to depth 1.
                if depth >= 1 {
                    opened = true;
                }
                continue;
            }
            if depth == 0 && before >= 1 {
                out.push(std::mem::take(buf));
                cur = None;
                continue;
            }
            buf.push_str(line.trim_end());
            buf.push('\n');
        }
        out
    }

    /// Normalise for comparison: drop blank lines and leading indentation, which
    /// the artifact's formatter may have changed without changing the kernel.
    fn norm_body(s: &str) -> String {
        s.lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// Five committed artifacts ship kernels that ALSO have a tile-rs emitter
    /// (`attention`, `norm_rms`, `rope`, `softmax`, `sum_rows`); the other 58 in
    /// that directory were hand-ported from antirez and have no emitter at all.
    ///
    /// Parity is the PRECONDITION for giving any of them a contract row. A
    /// contract table is generated by RUNNING the emitter and recording what it
    /// charges — so if the emitter has drifted from the committed artifact, the
    /// resulting contract describes a kernel nobody dispatches. That is worse
    /// than no contract, because the host then trusts it. Establish parity
    /// first, register second.
    #[test]
    fn ported_artifacts_still_match_their_emitters() {
        type Emit = fn(&mut String, &str);
        const CASES: &[(&str, Emit)] = &[
            ("attention", emit_attention_msl),
            ("norm_rms", emit_rms_norm_msl),
            ("rope", emit_rope_msl),
            ("softmax", |o: &mut String, _t: &str| emit_softmax_row_f32_simd8_msl(o)),
            ("sum_rows", emit_sum_rows_msl),
        ];

        // Artifacts whose COMMITTED body was hand-optimized past its emitter —
        // float4 vectorization, simd_sum, cross-SIMD shmem reduction, the
        // 8-SIMD max trick. For these the ARTIFACT is the source of truth and
        // the emitter is stale, so they must NOT be given emitter-derived
        // contracts: the contract would describe a slower, different kernel
        // than the one dispatched.
        //
        // Listing them here is the point — the drift is now recorded rather
        // than discovered again later. Removing an entry requires either
        // re-syncing the emitter to the artifact or deleting the dead emitter.
        const EMITTER_IS_STALE: &[&str] = &[];

        let mut drifted = Vec::new();
        let mut checked = 0usize;
        for (stem, emit) in CASES {
            let p = concat!(env!("CARGO_MANIFEST_DIR"), "/../../benchmarks/ds4_msl/emitted/")
                .to_string()
                + stem
                + ".metal";
            let committed = match std::fs::read_to_string(&p) {
                Ok(s) => s,
                Err(e) => {
                    drifted.push(format!("{stem}: read {p}: {e}"));
                    continue;
                }
            };
            let mut fresh = String::new();
            emit(&mut fresh, "float");

            let want = kernel_bodies(&committed);
            assert!(
                !want.is_empty(),
                "no kernel body parsed out of committed {stem}.metal — this \
                 check would pass vacuously"
            );
            // The emitter writes ONE body; the artifact ships one kernel.
            if want.len() != 1 {
                drifted.push(format!(
                    "{stem}: committed ships {} kernels, expected 1",
                    want.len()
                ));
                continue;
            }
            // The committed body is CALLER PREAMBLE + emitter output: besides the
            // signature, `convert_mlir_to_msl` emits per-kernel setup lines such
            // as `uint base = row * num_elements;` from the MLIR. So parity means
            // the emitter output is a SUFFIX of the committed body, not equality.
            //
            // Getting this wrong is not academic — comparing for equality
            // reported sum_rows and norm_rms as drifted purely because of that
            // one preamble line, which would have kept two artifacts off
            // contract coverage for no reason.
            let cw = norm_body(&want[0]);
            let cf = norm_body(&fresh);
            let differs = !cw.ends_with(&cf);
            let known_stale = EMITTER_IS_STALE.contains(stem);
            if differs && !known_stale {
                drifted.push(format!("{stem}: body differs from its emitter"));
            }
            if !differs && known_stale {
                drifted.push(format!(
                    "{stem} now MATCHES its emitter but is still listed in \
                     EMITTER_IS_STALE — remove it from the ledger so it becomes \
                     eligible for an emitter-derived contract"
                ));
            }
            checked += 1;
        }

        assert!(
            drifted.is_empty(),
            "committed artifact(s) have DRIFTED from their emitters:\n  {}\n\
             A contract generated from a drifted emitter would describe a kernel \
             that is not the one shipped. Re-emit the artifact, or declare the \
             emitter dead — do not register a contract over the gap.",
            drifted.join("\n  ")
        );
        assert_eq!(
            checked,
            CASES.len(),
            "expected all {} emitter-backed artifacts to be compared, checked \
             {checked} — this gate was inspecting less than it claims",
            CASES.len()
        );
    }

