    #[test]
    fn t_emit_mul_mv_q4_K_f32_msl() {
        // Dense (non-id) Q4_K matvec: same block_q4_K decode as the id sibling,
        // but standard dense weight offset and single-stage simd_sum finalize.
        // block_q4_K = 144 B (half d + half dmin + uchar scales[12] + uchar qs[128]).
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "constexpr uint  Q4K_BLOCK_BYTES = 144u;", "emit_mul_mv_q4_K_f32_msl#block");
        // 6-bit sub-scale unpack via kmask1/2/3.
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "constexpr uint16_t KMASK1 = 0x3f3f;", "emit_mul_mv_q4_K_f32_msl#kmask");
        // dmin (dh[1]) minimum-scale term present.
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "half d + half dmin", "emit_mul_mv_q4_K_f32_msl#dmin");
        // Single-stage simd_sum reduce (dense finalize, not helper_mv_reduce_and_write).
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "const float tot = simd_sum(sumf[row]);", "emit_mul_mv_q4_K_f32_msl#simd_sum");
        // Dense weight base: p0 + offset0 with NO id/expert (i02) indexing.
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "device const char  * x_base = p0 + offset0;", "emit_mul_mv_q4_K_f32_msl#dense_offset");
        // Same per-block q1 decode idiom as the id-routed emitter (byte-identical inner).
        check(|o| emit_mul_mv_q4_K_f32_msl(o), "device const uint16_t * q1 = (device const uint16_t *)(x_base + (uint)ib * Q4K_BLOCK_BYTES + 16u) + (uint)(16 * iq + 4 * ir);", "emit_mul_mv_q4_K_f32_msl#q1");
    }
