    /// ne00=512 (16 MXFP4 blocks/row), ne0=16 rows, 6 expert slots, 1 token.
    /// nb01 = 16*17 = 272; nb02 = 16*272 = 4352; nb11 = 512*4 = 2048;
    /// nb12 = 6*2048 = 12288; nb1 = 16*4 = 64; nbi1 = 6*4 = 24.
    #[test]
    #[ignore]
    fn mxfp4_sum6_numeric_ab() {
        let dev = Device::system_default().expect("no Metal device");
        let p = pso(
            &dev,
            &mxfp4_sum6_emitted_source(),
            "ds4_kernel_mul_mv_id_mxfp4_sum6_f32",
        );
        let (ne00, ne0, n_expert, n_slots) = (512usize, 16usize, 16usize, 6usize);
        let nblk = ne00 / 32;
        let row_bytes = nblk * MXFP4_BYTES;
        let expert_bytes = ne0 * row_bytes;

        // Pseudo-random blocks. Every byte is legal MXFP4 — e8m0 has no NaN
        // encoding and every nibble indexes the codebook — so no fixing-up is
        // needed, unlike the K-quants whose f16 scales can land on NaN.
        let mut x = vec![0u8; n_expert * expert_bytes];
        let mut st = 0xA5A5_1234u32;
        for b in x.iter_mut() {
            st ^= st << 13;
            st ^= st >> 17;
            st ^= st << 5;
            *b = (st & 0xff) as u8;
        }
        // Keep exponents in a sane range so the sum stays well-scaled.
        for e in 0..n_expert {
            for r in 0..ne0 {
                for ib in 0..nblk {
                    x[e * expert_bytes + r * row_bytes + ib * MXFP4_BYTES] = 120 + (ib as u8 % 12);
                }
            }
        }
        let ids: Vec<i32> = vec![3, 11, 0, 7, 15, 2];
        let y: Vec<f32> = (0..n_slots * ne00)
            .map(|i| ((i * 37 % 41) as f32 - 20.0) * 0.03)
            .collect();

        let xb = shared_buf(&dev, &x);
        let yb = shared_buf(&dev, &y);
        let ib_ = shared_buf(&dev, &ids);
        let ob = dev.new_buffer((ne0 * 4) as u64, MTLResourceOptions::StorageModeShared);

        let q = dev.new_command_queue();
        let cb = q.new_command_buffer();
        let enc = cb.new_compute_command_encoder();
        enc.set_compute_pipeline_state(&p);
        enc.set_buffer(0, Some(&xb), 0);
        enc.set_buffer(1, Some(&yb), 0);
        enc.set_buffer(2, Some(&ob), 0);
        enc.set_buffer(3, Some(&ib_), 0);
        for (i, v) in [
            ne00 as u32,
            ne0 as u32,
            24u32,
            row_bytes as u32,
            expert_bytes as u32,
            (ne00 * 4) as u32,
            (n_slots * ne00 * 4) as u32,
            (ne0 * 4) as u32,
        ]
        .iter()
        .enumerate()
        {
            enc.set_bytes((4 + i) as u64, 4, v as *const u32 as *const _);
        }
        // NSG=2 simdgroups x NR0=2 rows = 4 rows per threadgroup, 64 threads.
        enc.dispatch_thread_groups(
            MTLSize { width: (ne0 as u64).div_ceil(4), height: 1, depth: 1 },
            MTLSize { width: 64, height: 1, depth: 1 },
        );
        enc.end_encoding();
        cb.commit();
        cb.wait_until_completed();

        let got = unsafe { std::slice::from_raw_parts(ob.contents() as *const f32, ne0) };

        // Oracle in f64: the GPU reduces with simd_sum over a different order, and
        // an f32 CPU sum is a second opinion rather than a reference (the q6_K
        // routed-down gate read 1.06e-4 for exactly this reason).
        let mut want = vec![0f32; ne0];
        let mut blkbuf = [0f32; 32];
        for (row, w) in want.iter_mut().enumerate() {
            let mut acc = 0f64;
            for (slot, &e) in ids.iter().enumerate() {
                let base = e as usize * expert_bytes + row * row_bytes;
                for ib in 0..nblk {
                    let o = base + ib * MXFP4_BYTES;
                    mxfp4_dequant_block(&x[o..o + MXFP4_BYTES], &mut blkbuf);
                    for k in 0..32 {
                        acc += blkbuf[k] as f64 * y[slot * ne00 + ib * 32 + k] as f64;
                    }
                }
            }
            *w = acc as f32;
        }
        let (mut max_abs, mut max_rel) = (0f32, 0f32);
        for r in 0..ne0 {
            let abs = (got[r] - want[r]).abs();
            max_abs = max_abs.max(abs);
            max_rel = max_rel.max(abs / want[r].abs().max(1e-3));
        }
        println!(
            "ds4 mxfp4 sum6  tile-rs-emitted vs CPU oracle: max_abs={max_abs:.3e} max_rel={max_rel:.3e} (ne0={ne0}, ne00={ne00}, slots={n_slots})"
        );
        assert!(
            max_rel < 1e-5,
            "mxfp4 sum6 diverges from the oracle: max_rel={max_rel:.3e}"
        );
    }

    // ── plain (non-routed) q5_K matvec numeric A/B ─────────────────────────

    const Q5K_BYTES: usize = 176; // half d + half dmin + u8 scales[12] + u8 qh[32] + u8 qs[128]

    /// Reference q5_K block decode, straight from the ggml layout: 6-bit packed
    /// scale/min pairs (get_scale_min_k4), 4 low bits from qs plus one high bit
    /// from qh, value = d*scale*q - dmin*min.
    fn q5k_dequant_block(blk: &[u8], y: &mut [f32]) {
        let d = f16_to_f32(u16::from_le_bytes([blk[0], blk[1]]));
        let dmin = f16_to_f32(u16::from_le_bytes([blk[2], blk[3]]));
        let sc = &blk[4..16];
        let qh = &blk[16..48];
        let qs = &blk[48..176];
        for j in 0..QK_K {
            let g = j >> 5;
            let i = j & 31;
            let (sd, sm) = if g < 4 {
                ((sc[g] & 63) as u32, (sc[g + 4] & 63) as u32)
            } else {
                (
                    ((sc[g + 4] & 0x0F) as u32) | (((sc[g - 4] >> 6) as u32) << 4),
                    ((sc[g + 4] >> 4) as u32) | (((sc[g] >> 6) as u32) << 4),
                )
            };
            let shift = (g & 1) * 4;
            let mut v = ((qs[(g >> 1) * 32 + i] >> shift) & 0x0F) as u32;
            if qh[i] & (1u8 << g) != 0 {
                v += 16;
            }
            y[j] = d * sd as f32 * v as f32 - dmin * sm as f32;
        }
    }

